const crypto = require('crypto');
const item = $input.first().json;
const rawPayload = item.body || item;

// Source scope key: prevents cross-source mapping-cache pollution.
// Header is authoritative; payload 'source' is a convenience fallback (spoofable - documented). 
const sourceId =
  (item.headers && (item.headers['x-source-id'] || item.headers['X-Source-Id'])) ||
  (rawPayload && rawPayload.source) ||
  'default_source';

// Recursive canonical serialization: sort keys at EVERY nesting level.
// (JSON.stringify's array replacer silently drops nested keys - do NOT use it.)
function canonicalize(val) {
  if (val === null || typeof val !== 'object') return val;
  if (Array.isArray(val)) return val.map(canonicalize);
  return Object.keys(val).sort().reduce((acc, key) => {
    acc[key] = canonicalize(val[key]);
    return acc;
  }, {});
}

const canonicalJson = JSON.stringify(canonicalize(rawPayload));
const fingerprint = crypto.createHash('sha256').update(canonicalJson).digest('hex');
// Fall back to the fingerprint so business_leads.event_id (NOT NULL) never receives null
const eventId = rawPayload.event_id || fingerprint;
const idempotencyKey = `${sourceId}:${rawPayload.event_id || fingerprint}`;

return [{ json: { sourceId, idempotencyKey, eventId, rawPayload } }];

const fp = $('Extract & Fingerprint').first().json;
const rawPayload = fp.rawPayload;
const mappingRows = $('Load Active Mappings').all()
  .map(r => r.json)
  .filter(r => r && r.rule_id);

const normalized = { ...rawPayload };
const appliedRules = [];
for (const row of mappingRows) {
  if (normalized[row.target_key] === undefined && normalized[row.drifted_key] !== undefined) {
    normalized[row.target_key] = normalized[row.drifted_key];
    appliedRules.push(row.rule_id);
  }
}

return [{ json: { sourceId: fp.sourceId, idempotencyKey: fp.idempotencyKey, eventId: fp.eventId, rawPayload, normalized, appliedRules } }];

// Read from Normalize, NOT $input: the direct predecessor is Bump Hit Count (a Postgres
// node whose output is RETURNING rows, not the normalized payload).
const inp = $('Normalize').first().json;
const n = inp.normalized || {};
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const failures = [];
if (typeof n.customer_email !== 'string' || !EMAIL_RE.test(n.customer_email)) {
  failures.push('customer_email: expected non-empty email string');
}
if (typeof n.amount !== 'number' || !isFinite(n.amount)) {
  failures.push('amount: expected finite number');
}
if (typeof n.company !== 'string' || n.company.trim() === '') {
  failures.push('company: expected non-empty string');
}

// Type skeleton for the LLM: key names + type signatures only, never raw values (PII-safe)
function typeSignature(v) {
  if (typeof v === 'string') return EMAIL_RE.test(v) ? 'string (email)' : 'string';
  if (typeof v === 'number') return 'number';
  if (typeof v === 'boolean') return 'boolean';
  if (Array.isArray(v)) return 'array';
  if (v === null) return 'null';
  return typeof v === 'object' ? 'object' : 'unknown';
}
const received_skeleton = {};
for (const [k, v] of Object.entries(n)) received_skeleton[k] = typeSignature(v);

const expected_schema = { customer_email: 'string (email)', amount: 'number', company: 'string' };

return [{ json: { ...inp, valid: failures.length === 0, failures, expected_schema, received_skeleton } }];

const inp = $input.first().json;
const systemPrompt = [
  'You are a strict schema mapping validator.',
  'Input: an expected schema and a received skeleton (key names + type signatures only; values are redacted).',
  'Task: decide whether UNKNOWN received keys can be renamed 1:1 to the expected keys by semantic equivalence.',
  'Decision rule: a required field that is absent by name IS recoverable when exactly one unknown key is its semantic equivalent (a pure key rename).',
  'Set is_recoverable=true only if EVERY absent required field has exactly one such mapping and mapping covers them all.',
  'Set is_recoverable=false ONLY if: an absent required field has NO semantic counterpart, the mapping is ambiguous (multiple candidate keys), or a value transformation (unit conversion, computation, split/merge) would be required.',
  'NEVER map across units (e.g. total_cents -> amount) and never invent data.',
  'Respond ONLY with JSON: {"is_recoverable": boolean, "confidence": number (0-1), "mapping": {"drifted_key": "target_key"}, "unmapped_fields": [string], "reasoning": string}.'
].join(' ');
const userPrompt = JSON.stringify({
  expected_schema: inp.expected_schema,
  received_skeleton: inp.received_skeleton,
  validation_failures: inp.failures
});
return [{ json: { systemPrompt, userPrompt } }];

const resp = $input.first().json;
let verdict;
if (!resp || resp.error || !resp.choices) {
  // onError:continueRegularOutput lands here on HTTP failure (timeout / 401 / 429 / 5xx):
  // route to DLQ and mark failed instead of locking the idempotency key in PROCESSING
  verdict = { is_recoverable: false, confidence: 0, mapping: {}, unmapped_fields: [], reasoning: 'LLM call failed (timeout/auth/rate-limit/5xx): ' + JSON.stringify(resp && resp.error ? resp.error : resp).slice(0, 200) };
} else {
  try {
    const raw = resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
    verdict = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    verdict = { is_recoverable: false, confidence: 0, mapping: {}, unmapped_fields: [], reasoning: 'LLM response was not parseable JSON: ' + e.message };
  }
}
// Structural guard against hallucinated shapes
if (!verdict || typeof verdict !== 'object' || typeof verdict.confidence !== 'number' || typeof verdict.mapping !== 'object' || verdict.mapping === null) {
  verdict = { is_recoverable: false, confidence: 0, mapping: {}, unmapped_fields: [], reasoning: 'Verdict failed structural validation.' };
}
const prev = $('Contract Validation').first().json;
return [{ json: { ...prev, is_recoverable: !!verdict.is_recoverable, confidence: verdict.confidence, mapping: verdict.mapping, unmapped_fields: verdict.unmapped_fields || [], reasoning: verdict.reasoning || '' } }];

const crypto = require('crypto');
const inp = $input.first().json;
const out = [];
for (const [drifted, target] of Object.entries(inp.mapping)) {
  const sampleValue = inp.rawPayload ? inp.rawPayload[drifted] : undefined;
  const sampleHash = crypto.createHash('sha256').update(String(sampleValue)).digest('hex');
  out.push({ json: {
    rule_id: `${inp.sourceId}:${drifted}`,
    source_id: inp.sourceId,
    drifted_key: drifted,
    target_key: target,
    confidence: inp.confidence,
    sample_value_hash: sampleHash,
    reasoning: inp.reasoning
  } });
}
return out;

const inp = $('Contract Validation').first().json;
const mapping = $('Parse Healer Verdict').first().json.mapping;
const normalized = { ...inp.normalized };
for (const [drifted, target] of Object.entries(mapping)) {
  if (normalized[target] === undefined && normalized[drifted] !== undefined) {
    normalized[target] = normalized[drifted];
  }
}
return [{ json: {
  sourceId: inp.sourceId,
  idempotencyKey: inp.idempotencyKey,
  eventId: inp.eventId,
  normalized,
  rawPayload: inp.rawPayload,
  selfHealed: true,
  driftAlert: {
    message: 'Schema drift detected and auto-healed',
    source_id: inp.sourceId,
    mapping,
    confidence: $('Parse Healer Verdict').first().json.confidence,
    reasoning: $('Parse Healer Verdict').first().json.reasoning
  }
} }];

const inp = $input.first().json;
const n = inp.normalized || {};
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

// LLM mappings must survive the SAME deterministic contract before anything is
// persisted or cached. Without this, a hallucinated or partial mapping would
// silently write nulls - exactly the "green light dirty write" this workflow
// exists to prevent.
const failures = [];
if (typeof n.customer_email !== 'string' || !EMAIL_RE.test(n.customer_email)) {
  failures.push('customer_email: expected non-empty email string');
}
if (typeof n.amount !== 'number' || !isFinite(n.amount)) {
  failures.push('amount: expected finite number');
}
if (typeof n.company !== 'string' || n.company.trim() === '') {
  failures.push('company: expected non-empty string');
}

return [{ json: { ...inp, valid: failures.length === 0, healedFailures: failures } }];

const attempted = $('Mapping To Rows').all().length;
const accepted = $input.all().filter(r => r.json && r.json.rule_id).length;
return [{ json: { accepted: accepted > 0 && accepted === attempted, attempted, acceptedCount: accepted } }];

// Single assembly point for both persist paths: direct pass and self-healed.
const v = $('Validate Healed Record').isExecuted
  ? $('Validate Healed Record').first().json
  : $('Contract Validation').first().json;
return [{ json: { sourceId: v.sourceId, eventId: v.eventId, normalized: v.normalized, rawPayload: v.rawPayload } }];

const crypto = require('crypto');
const govRan = $('Check Mapping Governance').isExecuted;
const govRejected = govRan && $('Check Mapping Governance').first().json.accepted === false;
const lastValidation = $('Validate Healed Record').isExecuted
  ? $('Validate Healed Record').first().json
  : $('Contract Validation').first().json;
const healerRan = $('Parse Healer Verdict').isExecuted;
const reasonBase = govRejected
  ? 'Learned mapping rejected by governance (previously revoked by operator)'
  : healerRan
    ? 'LLM could not safely map: ' + (($('Parse Healer Verdict').first().json.reasoning) || '')
    : 'Contract validation failed';
const failures = lastValidation.healedFailures || lastValidation.failures || [];

return [{ json: {
  dlq_id: crypto.randomUUID(),
  sourceId: lastValidation.sourceId,
  idempotencyKey: $('Extract & Fingerprint').first().json.idempotencyKey,
  payloadJson: JSON.stringify(lastValidation.rawPayload),
  failureReason: (reasonBase + ' | failures: ' + JSON.stringify(failures)).slice(0, 500)
} }];
